-- UNDO for the six social website migrations 20261101100000 .. 20261105100000. GENERATED by supabase/go-live/build_social.py: do not edit it by hand. One transaction.
--
-- IT REFUSES (and changes nothing) while people's content exists: any post, comment, message, review, report or follow. Those are people's words and pictures; switch the features
-- off in the CMS (Social settings) instead, which hides the whole social side without deleting anything. This undo is for a launch that never opened (or a test project).
-- IT ALSO REFUSES while the media bucket holds files (delete them in the dashboard first: the database cannot delete a file).
-- WHAT IT REMOVES: the triggers, the three storage policies and the bucket, every function and table the migrations created (with the data in them: profiles, usernames, blocks,
-- notification choices, the community rules text and what people accepted, the feature switches), and the columns and constraints they added to existing tables.
-- WHAT STAYS: everything that existed before, and the audit log (it is history).
-- AFTER IT: redeploy nothing; the customer app and the CMS pages handle "not set up on this server yet" and show nothing social.
begin;

do $refuse$
begin
  if to_regclass('public.site_posts') is not null and exists (select 1 from public.site_posts) then
    raise exception 'there are posts: that is people''s content, so it is kept (switch the features off in the CMS instead). Nothing was changed.';
  end if;
  if to_regclass('public.site_comments') is not null and exists (select 1 from public.site_comments) then
    raise exception 'there are comments: that is people''s content, so it is kept (switch the features off in the CMS instead). Nothing was changed.';
  end if;
  if to_regclass('public.site_dm_messages') is not null and exists (select 1 from public.site_dm_messages) then
    raise exception 'there are messages: that is people''s content, so it is kept (switch the features off in the CMS instead). Nothing was changed.';
  end if;
  if to_regclass('public.site_reviews') is not null and exists (select 1 from public.site_reviews) then
    raise exception 'there are reviews: that is people''s content, so it is kept (switch the features off in the CMS instead). Nothing was changed.';
  end if;
  if to_regclass('public.site_reports') is not null and exists (select 1 from public.site_reports) then
    raise exception 'there are reports: that is people''s content, so it is kept (switch the features off in the CMS instead). Nothing was changed.';
  end if;
  if to_regclass('public.site_follows') is not null and exists (select 1 from public.site_follows) then
    raise exception 'there are follows: that is people''s content, so it is kept (switch the features off in the CMS instead). Nothing was changed.';
  end if;
  if exists (select 1 from storage.objects where bucket_id = 'social-media') then
    raise exception 'the social-media bucket still holds files: delete them in the dashboard first. Nothing was changed.';
  end if;
end
$refuse$;

-- triggers
drop trigger if exists site_handles_follow_profile on public.profiles;
drop trigger if exists site_follows_notify on public.site_follows;
drop trigger if exists site_post_likes_notify on public.site_post_likes;
drop trigger if exists site_comments_notify on public.site_comments;
drop trigger if exists site_post_tags_notify on public.site_post_tags;
drop trigger if exists site_review_replies_notify on public.site_review_replies;

-- the storage policies and the bucket
drop policy if exists "social media readable by those who may see the post" on storage.objects;
drop policy if exists "profiles add their own social media" on storage.objects;
drop policy if exists "profiles remove their own social media" on storage.objects;
delete from storage.buckets where id = 'social-media';

-- every function the migrations created (all overloads of each name)
do $d$
declare r record;
begin
  for r in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = any(array['ai_caption_begin', 'block_list', 'block_set', 'cms_find_profiles', 'cms_list_banned_terms', 'cms_list_features', 'cms_profile_set_status', 'cms_publish_rules', 'cms_report_resolve', 'cms_reports_list', 'cms_set_banned_term', 'cms_set_feature', 'comment_add', 'comment_card', 'comment_delete', 'comment_list', 'dm_answer_request', 'dm_conversation', 'dm_conversation_json', 'dm_delete_message', 'dm_direct_closed', 'dm_group_add', 'dm_group_remove', 'dm_group_rename', 'dm_inbox', 'dm_is_member', 'dm_leave', 'dm_mark_read', 'dm_message_card', 'dm_messages', 'dm_mute', 'dm_new_member_status', 'dm_people', 'dm_ref_card', 'dm_require_inbox', 'dm_send', 'dm_start_booking', 'dm_start_direct', 'dm_start_group', 'dm_unread', 'explore_hot_events', 'explore_hot_venues', 'explore_professionals', 'feature_enabled', 'feed_home', 'feed_reels', 'feed_suggested', 'follow_list', 'follow_requests', 'follow_respond', 'follow_set', 'handle_available', 'handle_reserved', 'members_list', 'members_set', 'moderation_person_profiles', 'notification_prefs', 'notification_prefs_set', 'notifications_list', 'notifications_purge', 'notifications_read', 'notifications_unread', 'notify_on_comment', 'notify_on_follow', 'notify_on_like', 'notify_on_review_reply', 'notify_on_tag', 'notify_profile', 'post_card', 'post_create', 'post_delete', 'post_edit', 'post_get', 'post_like', 'post_save', 'post_untag', 'post_visible', 'profile_blocked_between', 'profile_can_act_as', 'profile_card', 'profile_clean_interests', 'profile_content_visible', 'profile_create_business', 'profile_get', 'profile_is_mine', 'profile_key', 'profile_mini', 'profile_my_ids', 'profile_my_profiles', 'profile_posts', 'profile_require_actor', 'profile_save_personal', 'profile_search', 'profile_update_business', 'profile_visible', 'report_create', 'review_can_reply', 'review_card', 'review_delete', 'review_eligibility', 'review_reply', 'review_reply_delete', 'review_save', 'review_summary', 'review_visited', 'reviews_list', 'rules_accept', 'rules_current', 'rules_status', 'save_venue_facts', 'saved_posts', 'site_features', 'site_handles_follow_profile', 'social_housekeeping', 'social_json_int', 'social_media_can_add', 'social_media_orphans', 'social_media_profile', 'social_media_visible', 'social_require_rules', 'social_rules_version', 'social_text_ok', 'stories_of', 'story_rail', 'story_seen', 'venue_ratings']::text[]) loop
    execute 'drop function ' || r.sig;
  end loop;
end
$d$;

-- every table the migrations created (they only point at each other and at people; nothing else points at them)
drop table if exists public.site_feature_flags, public.site_profiles, public.site_handles, public.site_follows, public.site_blocks, public.site_posts, public.site_post_media, public.site_post_tags, public.site_post_likes, public.site_post_saves, public.site_comments, public.site_member_lists, public.site_story_views, public.site_banned_terms, public.site_community_rules, public.site_ai_caption_uses, public.site_rules_acceptance, public.site_reviews, public.site_review_replies, public.site_dm_conversations, public.site_dm_members, public.site_dm_messages, public.site_notifications, public.site_notification_opt_outs, public.site_reports cascade;

-- the indexes they added to tables that existed before (dropping the new tables does not drop these)
drop index if exists public.profiles_username_prefix_idx;
drop index if exists public.profiles_name_prefix_idx;

-- what they added to existing tables
alter table public.site_venues drop constraint if exists site_venues_amenities_known;
alter table public.site_venues drop constraint if exists site_venues_facts_lengths;
alter table public.site_venues drop column if exists amenities, drop column if exists parking_info, drop column if exists min_age, drop column if exists id_required, drop column if exists last_entry, drop column if exists kitchen_hours, drop column if exists menu_url;

commit;
